        addNode("lobby_stand_entry", 0, 6, ["lobby_center"]);
        addNode("lobby_wc_back", -10.2, -8, ["lobby_center"]);

        // Cafe door connected to lobby center directly
        nodes["cafe_door"].neighbors = ["lobby_center"];

        const sitTargets = {};
