            addNode("office" + oid + "_desk", cx, -7.2, ["office" + oid + "_door"]);
        }

        // Conference room
        addNode("conf_door", -7, 3.0, ["hallSW"]);
        addNode("conf_center", -7, 6, ["conf_door"]);
        addNode("conf_seat0", -7.7, 6.95, ["conf_center"]);
        addNode("conf_seat1", -6.3, 6.95, ["conf_center"]);
