        addNode("lounge_spot0", 7, 7.5, ["lounge_center"]);   // facing -Z
        addNode("lounge_spot1", 7, 4.5, ["lounge_center"]);   // facing +Z
        addNode("lounge_spot2", 9, 8, ["lounge_center"]);     // facing -X
