                floorNumber: f,
                nodes: of.nodes,
                callPanel: of.callPanel,
                shaftIndicator: of.shaftIndicator,
                desks: of.desks,
                sitTargets: of.sitTargets,
            });
        }

        scene.add(buildingGroup);

        return {
            buildingGroup: buildingGroup,
            floors: floors,
            bfsPath: bfsPath,
            world: WORLD,
        };
    }

    root.WORLD = WORLD;
    root.createWorld = createWorld;
    root.bfsPath = bfsPath;
